import {announce} from '@github-ui/aria-live'
import {verifiedFetch} from '@github-ui/verified-fetch'
import {TrashIcon} from '@primer/octicons-react'
import {Banner, Button, Spinner} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {useEffect, useRef, useState} from 'react'

type MemoryAdminDeleteResponse = {
  state?: 'none' | 'queued' | 'started' | 'success' | 'error'
  jobStatusUrl?: string
  error?: string
}

type MemoryAdminDeleteNotification = {
  message: string
  variant: 'critical' | 'warning' | 'success'
}

type MemoryAdminDeleteDialogProps = {
  isOpen: boolean
  onClose: () => void
  entityName: string
  /**
   * The base URL for delete operations, used for both GET (status) and POST (create).
   * When deleting a single user's memories the URL already carries `target_user_id`.
   */
  memoryDeleteUrl?: string | null
  targetUserLogin?: string
}

const POLLING_INTERVAL_MS = 2_000
const MAX_POLLING_DURATION_MS = 15 * 60 * 1000
const MEMORY_DELETE_REQUEST_ERROR_MESSAGE = "We couldn't delete these memories. Please try again later."
const MEMORY_DELETE_STATUS_ERROR_MESSAGE = "We couldn't check the delete status. Please try again later."
const MEMORY_DELETE_CONFLICT_MESSAGE = 'A memory delete is already in progress for this scope.'
const MEMORY_DELETE_RATE_LIMITED_MESSAGE = "You've made too many delete requests. Please try again later."
const MEMORY_DELETE_SUCCESS_MESSAGE = 'User memories have been permanently deleted.'
const MEMORY_DELETE_POLLING_TIMEOUT_MESSAGE =
  'This delete is taking longer than expected. You can close this dialog and check again later.'

class MemoryAdminDeletePollingTimeoutError extends Error {
  constructor() {
    super(MEMORY_DELETE_POLLING_TIMEOUT_MESSAGE)
    this.name = 'MemoryAdminDeletePollingTimeoutError'
  }
}

class MemoryAdminDeletePollingAbortError extends Error {
  constructor() {
    super('copilot_memory_admin_delete_polling_aborted')
    this.name = 'MemoryAdminDeletePollingAbortError'
  }
}

function isAbortError(error: unknown): boolean {
  return (
    error instanceof MemoryAdminDeletePollingAbortError ||
    (error instanceof DOMException && error.name === 'AbortError')
  )
}

async function wait(ms: number, signal?: AbortSignal): Promise<void> {
  if (signal?.aborted) throw new MemoryAdminDeletePollingAbortError()

  return new Promise((resolve, reject) => {
    const abort = () => {
      clearTimeout(timeout)
      reject(new MemoryAdminDeletePollingAbortError())
    }
    const timeout = setTimeout(() => {
      signal?.removeEventListener('abort', abort)
      resolve()
    }, ms)
    signal?.addEventListener('abort', abort, {once: true})
  })
}

async function getMemoryAdminDeleteResponse(response: Response): Promise<MemoryAdminDeleteResponse | null> {
  if (response.status === 204) return null

  return (await response.json()) as MemoryAdminDeleteResponse
}

async function pollMemoryAdminDeleteJob(
  url: string,
  startedAt = Date.now(),
  signal?: AbortSignal,
): Promise<MemoryAdminDeleteResponse | null> {
  if (signal?.aborted) throw new MemoryAdminDeletePollingAbortError()

  if (Date.now() - startedAt >= MAX_POLLING_DURATION_MS) {
    throw new MemoryAdminDeletePollingTimeoutError()
  }

  const response = signal ? await verifiedFetch(url, {signal}) : await verifiedFetch(url)
  const data = await getMemoryAdminDeleteResponse(response)

  if (response.status === 202) {
    await wait(POLLING_INTERVAL_MS, signal)
    return pollMemoryAdminDeleteJob(url, startedAt, signal)
  }

  if (response.status > 399 || data?.error || data?.state === 'error') {
    throw new Error(MEMORY_DELETE_REQUEST_ERROR_MESSAGE)
  }

  return data
}

// Treat a settled (non-202) poll result as a completed delete. The backend keeps
// terminal `success` status only briefly and then reports `none` once the status is
// cleaned up, so both `success` and `none` (and an empty 204 body) mean the delete
// finished. An `error` state is handled earlier by throwing in the poller.
function isDeleteCompleted(data: MemoryAdminDeleteResponse | null): boolean {
  return data == null || data.state === 'success' || data.state === 'none'
}

function notificationForError(error: unknown, fallbackMessage: string): MemoryAdminDeleteNotification {
  if (error instanceof MemoryAdminDeletePollingTimeoutError) {
    return {message: MEMORY_DELETE_POLLING_TIMEOUT_MESSAGE, variant: 'warning'}
  }

  return {message: fallbackMessage, variant: 'critical'}
}

export function MemoryAdminDeleteDialog({
  isOpen,
  onClose,
  entityName,
  memoryDeleteUrl,
  targetUserLogin,
}: MemoryAdminDeleteDialogProps) {
  const [isSubmitting, setIsSubmitting] = useState(false)
  const [isWaitingForActiveDelete, setIsWaitingForActiveDelete] = useState(false)
  const [isCheckingActiveDelete, setIsCheckingActiveDelete] = useState(false)
  const [deleteCompleted, setDeleteCompleted] = useState(false)
  const [notification, setNotification] = useState<MemoryAdminDeleteNotification | null>(null)
  const dialogSessionIdRef = useRef(0)
  const requestIdRef = useRef(0)
  const requestAbortControllerRef = useRef<AbortController | null>(null)
  const isDeleting = isSubmitting || isWaitingForActiveDelete
  const isConfirmButtonBusy = isCheckingActiveDelete || isDeleting
  const confirmButtonText = isCheckingActiveDelete
    ? 'Checking delete status...'
    : isDeleting
      ? 'Deleting memories...'
      : 'Delete memories'

  useEffect(() => {
    if (isCheckingActiveDelete) {
      announce('Checking delete status...')
    } else if (isDeleting) {
      announce('Deleting memories...')
    }
  }, [isCheckingActiveDelete, isDeleting])

  useEffect(() => {
    if (notification) announce(notification.message)
  }, [notification])

  useEffect(() => {
    // Each time the dialog opens, bump the session id so any stale async
    // callbacks from a previous open are ignored.
    if (isOpen) {
      dialogSessionIdRef.current += 1
    }
  }, [isOpen])

  useEffect(() => {
    if (!isOpen || !memoryDeleteUrl) return

    let cancelled = false
    const abortController = new AbortController()

    const checkActiveDelete = async () => {
      setDeleteCompleted(false)
      setNotification(null)
      setIsWaitingForActiveDelete(false)
      setIsCheckingActiveDelete(true)

      try {
        const response = await verifiedFetch(memoryDeleteUrl, {
          headers: {Accept: 'application/json'},
          signal: abortController.signal,
        })
        const data = await getMemoryAdminDeleteResponse(response)
        if (cancelled || !data) return

        if (response.status === 202 && data.jobStatusUrl) {
          // A delete is already running for this scope — wait then poll to completion.
          setIsWaitingForActiveDelete(true)
          setIsCheckingActiveDelete(false)
          await wait(POLLING_INTERVAL_MS, abortController.signal)
          const completedJob = await pollMemoryAdminDeleteJob(data.jobStatusUrl, Date.now(), abortController.signal)
          if (!cancelled && isDeleteCompleted(completedJob)) {
            setDeleteCompleted(true)
            setNotification({message: MEMORY_DELETE_SUCCESS_MESSAGE, variant: 'success'})
          }
        } else if (response.status > 399 || data.error || data.state === 'error') {
          throw new Error(data.error || MEMORY_DELETE_STATUS_ERROR_MESSAGE)
        }
        // A terminal `success` or `none` state means no active delete — the dialog
        // stays ready so the admin can start a new delete for the same scope.
      } catch (error) {
        if (!cancelled && !isAbortError(error)) {
          setNotification(notificationForError(error, MEMORY_DELETE_STATUS_ERROR_MESSAGE))
        }
      } finally {
        if (!cancelled) {
          setIsCheckingActiveDelete(false)
          setIsWaitingForActiveDelete(false)
        }
      }
    }

    void checkActiveDelete()

    return () => {
      cancelled = true
      abortController.abort()
    }
  }, [isOpen, memoryDeleteUrl])

  const resetDialogState = () => {
    dialogSessionIdRef.current += 1
    requestAbortControllerRef.current?.abort()
    requestAbortControllerRef.current = null
    setNotification(null)
    setDeleteCompleted(false)
    setIsSubmitting(false)
    setIsCheckingActiveDelete(false)
    setIsWaitingForActiveDelete(false)
  }

  const closeDialog = () => {
    resetDialogState()
    onClose()
  }

  const submitDelete = async (): Promise<void> => {
    // `isSubmitting` is React state and updates asynchronously, so guard against a
    // rapid double-invocation synchronously via the in-flight request ref.
    if (!memoryDeleteUrl || isSubmitting || isWaitingForActiveDelete || requestAbortControllerRef.current) return

    const currentDialogSessionId = dialogSessionIdRef.current
    const currentRequestId = requestIdRef.current + 1
    requestIdRef.current = currentRequestId
    const abortController = new AbortController()
    requestAbortControllerRef.current = abortController
    const canUpdateDialog = () => dialogSessionIdRef.current === currentDialogSessionId
    const isLatestRequest = () => requestIdRef.current === currentRequestId

    setIsSubmitting(true)
    setNotification(null)
    try {
      const response = await verifiedFetch(memoryDeleteUrl, {method: 'POST', signal: abortController.signal})

      if (response.status === 409) {
        if (!canUpdateDialog()) return
        setNotification({message: MEMORY_DELETE_CONFLICT_MESSAGE, variant: 'warning'})
        return
      }

      if (response.status === 429) {
        let rateLimited: MemoryAdminDeleteResponse | null = null
        try {
          rateLimited = (await response.json()) as MemoryAdminDeleteResponse
        } catch {
          rateLimited = null
        }
        if (!canUpdateDialog()) return
        setNotification({message: rateLimited?.error || MEMORY_DELETE_RATE_LIMITED_MESSAGE, variant: 'warning'})
        return
      }

      const data = (await response.json()) as MemoryAdminDeleteResponse
      if (!canUpdateDialog()) return
      if (response.status > 399 || data.error) {
        throw new Error(data.error || MEMORY_DELETE_REQUEST_ERROR_MESSAGE)
      }
      if (!data.jobStatusUrl) throw new Error(MEMORY_DELETE_REQUEST_ERROR_MESSAGE)

      const completedJob = await pollMemoryAdminDeleteJob(data.jobStatusUrl, Date.now(), abortController.signal)
      if (!canUpdateDialog()) return

      if (isDeleteCompleted(completedJob)) {
        setDeleteCompleted(true)
        setNotification({message: MEMORY_DELETE_SUCCESS_MESSAGE, variant: 'success'})
      } else {
        throw new Error(MEMORY_DELETE_REQUEST_ERROR_MESSAGE)
      }
    } catch (error) {
      if (canUpdateDialog() && !isAbortError(error)) {
        setNotification(notificationForError(error, MEMORY_DELETE_REQUEST_ERROR_MESSAGE))
      }
    } finally {
      if (requestAbortControllerRef.current === abortController) {
        requestAbortControllerRef.current = null
      }
      if (isLatestRequest()) {
        setIsSubmitting(false)
      }
    }
  }

  const handleConfirm = () => {
    if (!deleteCompleted) {
      void submitDelete()
    }
  }

  if (!isOpen) return null

  const deleteDescription = targetUserLogin
    ? `This will permanently delete user-scoped Copilot memories for ${targetUserLogin} that are billed to ${entityName}.`
    : `This will permanently delete user-scoped Copilot memories for all users with Copilot seats billed to ${entityName}.`

  return (
    <Dialog title="Delete user memories?" onClose={closeDialog} data-testid="cfb-seats-memory-admin-delete-dialog">
      <p>{deleteDescription}</p>
      <p>This action cannot be undone. Deleted memories cannot be recovered.</p>
      <p>
        By clicking Delete memories, you confirm you have permission to perform this action on behalf of these users.
      </p>
      {notification && (
        <Banner
          variant={notification.variant}
          title={
            notification.variant === 'success'
              ? 'Memory delete completed'
              : notification.variant === 'warning'
                ? 'Memory delete is taking longer than expected'
                : 'Memory delete failed'
          }
          hideTitle
          description={notification.message}
          data-testid="cfb-seats-memory-admin-delete-notification"
        />
      )}
      <Dialog.Footer>
        <Button type="button" onClick={closeDialog} disabled={isDeleting}>
          {deleteCompleted ? 'Close' : 'Cancel'}
        </Button>
        {!deleteCompleted && (
          <Button
            type="button"
            variant="danger"
            onClick={handleConfirm}
            disabled={!memoryDeleteUrl || isCheckingActiveDelete || isDeleting}
            leadingVisual={isConfirmButtonBusy ? undefined : TrashIcon}
            aria-busy={isConfirmButtonBusy}
            data-testid="cfb-seats-memory-admin-delete-confirm-button"
          >
            {isConfirmButtonBusy ? (
              <>
                <Spinner size="small" className="mr-2" srText={null} />
                {confirmButtonText}
              </>
            ) : (
              confirmButtonText
            )}
          </Button>
        )}
      </Dialog.Footer>
    </Dialog>
  )
}
